window.kbPageData["views/entry/k-82c7b89123523601"] = {"key":"entry/k-82c7b89123523601","state":{"route":"entry/k-82c7b89123523601"},"node":{"id":"k-82c7b89123523601","mode":"k","title":"两项可加时的总量与分量变化","type":"原理与机制","domain":"科技","reading":"","intro":"","priority":100,"aliases":["两项可加时总量下降且一项上升可推出另一项下降"],"qs":["江苏 2024 A类 行测#95"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"总量等于两项之和时，总量的变化等于两项变化之和。若总量下降而其中一项上升，另一项必然下降，且降幅大于上升项的增量。","review":{"definition":"总量等于两项之和时，总量的变化等于两项变化之和。若总量下降而其中一项上升，另一项必然下降，且降幅大于上升项的增量。","explanation":"按本题的两项可加模型，若B项所说的锻炼时长增加带来活动能量消耗上升，静息代谢就必须下降才能使总量下降。因此B项能加强观点。若D项的降幅按同单位的绝对量比较，活动项比总量降得更多，静息项须上升以抵消部分降幅，方向与待支持的观点相反。原解析称D项下另一项的变化无法确定，这在上述可加模型和比较口径下有误。","references":[],"evidence":"总能量代谢水平下降幅度比活动能量代谢水平下降幅度小","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2024 A类 行测#95":{"paper":"江苏 2024 A类 行测","n":95,"mod":"判断推理","src":["f8fec75f67d6d1ba5759.pdf",19],"asrc":["0126a1c8aceee632ea2b.pdf",29],"card":"82037a0a76770f3bd03e93b1","links":[{"id":"k-82c7b89123523601","role":"解题依据","why":"当总量可按两项之和处理时，其中一项的下降须超过另一项的上升。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-82c7b89123523601":[["江苏 2024 A类 行测#95"]]}};
